<?php require 'config.php';
$count=(int)one('SELECT COUNT(*) AS n FROM users')['n']; if ($count) go('login.php');
$error=''; if ($_SERVER['REQUEST_METHOD']==='POST') { verify_post(); $name=trim($_POST['name']??''); $username=trim($_POST['username']??''); $pass=$_POST['password']??''; if (!$name||!$username||strlen($pass)<8) $error='Enter a name, username and password of at least 8 characters.'; else { try { stmt("INSERT INTO users (full_name,username,password_hash,role) VALUES (?,?,?,'admin')",'sss',[$name,$username,password_hash($pass,PASSWORD_DEFAULT)]); go('login.php'); } catch(Throwable $e){ $error='Username already exists or setup failed.'; } } }
